// Parse search parameters with metadata filters
const query = $json.query || $json.body?.query || '';
const limit = $json.limit || $json.body?.limit || 10;
const minScore = $json.min_score || $json.body?.min_score || 0.7;
const minQuality = $json.min_quality || $json.body?.min_quality || 0.0;

// Enhanced filters from Qdrant metadata
const filters = $json.filters || $json.body?.filters || {};

// Available filter fields:
// - department: QHSE, Engineering, Operations, etc.
// - document_type_category: process, form, template, policy, procedure
// - is_process, is_form, is_template: boolean flags
// - processing_profile: railway, technical, general
// - fleet_type, train_id, network_component: railway-specific
// - standard_compliance: ISO standards

return {
  json: {
    query,
    limit,
    min_score: minScore,
    min_quality: minQuality,
    filters,
    include_metadata: true
  }
};

// Format search results with rich metadata
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message,
      results: []
    }
  };
}

const results = (response.results || []).map(result => ({
  document_id: result.document_id,
  document_name: result.metadata?.document_name || result.document_name,
  document_type: result.metadata?.document_type || 'unknown',
  department: result.metadata?.department || 'unknown',
  document_type_category: result.metadata?.document_type_category || 'unknown',

  // Content
  content: result.text || result.content,
  content_preview: (result.text || result.content || '').substring(0, 300) + '...',

  // Scores
  relevance_score: result.score || 0,
  quality_score: result.metadata?.quality_score || 0,

  // Context
  chunk_index: result.chunk_key || result.metadata?.chunk_index,
  chunk_type: result.metadata?.chunk_type || 'unknown',
  hierarchy_level: result.metadata?.hierarchy_level || 'unknown',
  has_context: result.metadata?.has_context || false,

  // Railway-specific metadata
  fleet_type: result.metadata?.fleet_type || null,
  train_id: result.metadata?.train_id || null,
  network_component: result.metadata?.network_component || null,
  configuration_type: result.metadata?.configuration_type || null,

  // Document properties
  is_process: result.metadata?.is_process || false,
  is_form: result.metadata?.is_form || false,
  is_template: result.metadata?.is_template || false,

  // Standards
  standard_compliance: result.metadata?.standard_compliance || null,

  // URLs
  document_url: result.metadata?.document_url || result.source_url || null,

  // Processing info
  processing_profile: result.metadata?.processing_profile || 'railway',
  processing_version: result.metadata?.processing_version || 'unknown',

  // Entities and keywords
  entities: result.metadata?.entities ? JSON.parse(result.metadata.entities) : [],
  keywords: result.metadata?.keywords ? JSON.parse(result.metadata.keywords) : [],
  technical_terms: result.metadata?.technical_terms ? JSON.parse(result.metadata.technical_terms) : []
}));

return {
  json: {
    success: true,
    results,
    metadata: {
      query: response.query,
      total_results: results.length,
      search_type: 'semantic',
      min_score_applied: response.min_score || 0.7,
      min_quality_applied: response.min_quality || 0.0
    }
  }
};
